#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# dot9 builds on box3900x, in /build/monerodato-dot9 (worktree of ~/work/monerodato, branch dot9-prep):
#  1. submodules from the main checkout's modules;
#  2. release-recipe daemons (depends toolchain of /build/monerodato-bpp: contrib/depends is unchanged .7 -> .9,
#     checked here; cmake Ninja Release ARCH=default STATIC=ON BUILD_TESTS=OFF), each in its own build dir:
#     B8 = e7bae3ecf (.8) in build/rel-dot8, N = dot9-prep in build/rel-dot9; copies to research-artifacts/dot9/;
#  3. unit_tests (system toolchain, Release, BUILD_TESTS=ON) in build/tests at dot9-prep; the new tests, then all;
#  4. crate tests in patched/monero-oxide: generalized-bulletproofs --features tests, full-chain-membership-proofs.
# Log ~/work/g016/build_dot9.log; marker BUILD_DOT9_DONE <ok|FAIL>.
set -uo pipefail
W=$HOME/work/g016; L=$W/build_dot9.log; SRC=$HOME/work/monerodato; R=/build/monerodato-dot9
OUT=$HOME/work/research-artifacts/dot9; TC=/build/monerodato-bpp/contrib/depends/x86_64-linux-gnu/share/toolchain.cmake
exec > $L 2>&1
fin() { echo "BUILD_DOT9_DONE $1 $(date -u +%FT%TZ)"; exit 0; }
echo "start $(date -u +%FT%TZ)"
[ "$(df --output=avail -BG / | tail -1 | tr -dc 0-9)" -ge 28 ] || { echo "under 28 GB free"; fin FAIL; }
. ~/.cargo/env; echo "$(rustc --version); $(gcc --version | head -1); $(cmake --version | head -1)"
cd $R || fin FAIL
[ -z "$(git status --porcelain --untracked-files=no)" ] || { echo "tree dirty"; fin FAIL; }
N=$(git rev-parse --short=9 dot9-prep); echo "dot9-prep $N"
[ -z "$(git diff --name-only f3c4ea5d9 dot9-prep -- contrib/depends)" ] || { echo "contrib/depends changed since .7"; fin FAIL; }
[ -f $TC ] || { echo "no toolchain file"; fin FAIL; }
git submodule init > /dev/null
for name in $(git config -f .gitmodules --get-regexp '^submodule\..*\.path$' | sed 's/^submodule\.\(.*\)\.path .*/\1/'); do
  git config submodule.$name.url $SRC/.git/modules/$name
done
git -c protocol.file.allow=always submodule update --init -q || fin FAIL
git submodule status | grep -E '^[-+U]' && { echo "a submodule is not at the tree's commit"; fin FAIL; }
mkdir -p $OUT
build() {	# <ref> <dir> <name>
  git checkout -q $1 && git submodule update -q || return 1
  [ -z "$(git status --porcelain --untracked-files=no)" ] || return 1
  mkdir -p build/$2
  (cd build/$2 && cmake -G Ninja -DCMAKE_TOOLCHAIN_FILE=$TC -DCMAKE_BUILD_TYPE=Release -DARCH=default -DSTATIC=ON -DBUILD_TESTS=OFF ../.. > $W/build_dot9_configure_$3.log 2>&1) || return 1
  nice -n 5 ninja -C build/$2 -j10 daemon > $W/build_dot9_ninja_$3.log 2>&1 || return 1
  cp -p build/$2/bin/monerod $OUT/monerod-$3
  echo "monerod-$3: $(sha256sum $OUT/monerod-$3 | cut -c1-16) $(stat -c %s $OUT/monerod-$3) B; $($OUT/monerod-$3 --version | tail -1); cargo: $(grep -c 'Compiling ' $W/build_dot9_ninja_$3.log) Compiling lines, generalized-bulletproofs $(grep -c 'Compiling generalized-bulletproofs ' $W/build_dot9_ninja_$3.log)"
}
echo "B8 build $(date -u +%FT%TZ)"
git checkout -q --detach e7bae3ecf && build HEAD rel-dot8 dot8-e7bae3ecf || { echo "B8 build FAILED"; fin FAIL; }
echo "N build $(date -u +%FT%TZ)"
build dot9-prep rel-dot9 dot9-$N || { echo "N build FAILED"; fin FAIL; }
cmp -s $OUT/monerod-dot8-e7bae3ecf $OUT/monerod-dot9-$N && { echo "B8 and N are identical"; fin FAIL; }
echo "== strings scan"
for b in $OUT/monerod-dot8-e7bae3ecf $OUT/monerod-dot9-$N; do echo "$(basename $b) $(strings -a $b | grep -aciE "$LAB_NAMES" || true)"; done
echo "unit_tests build $(date -u +%FT%TZ)"
mkdir -p build/tests
(cd build/tests && cmake -G Ninja -DCMAKE_BUILD_TYPE=Release -DARCH=default -DBUILD_TESTS=ON ../.. > $W/build_dot9_configure_tests.log 2>&1) || { echo "tests configure FAILED"; fin FAIL; }
nice -n 5 ninja -C build/tests -j10 unit_tests > $W/build_dot9_ninja_tests.log 2>&1 || { echo "unit_tests build FAILED"; tail -30 $W/build_dot9_ninja_tests.log; fin FAIL; }
UT=$R/build/tests/tests/unit_tests/unit_tests
echo "== new tests $(date -u +%FT%TZ)"
$UT --gtest_filter='ringct.semantics_batch_*:ringct.bpp_sub_batches_*:tx_verification_utils.keyimages_domain_batch' 2>&1 | grep -E '^\[ +(OK|FAILED|PASSED) |FAILED|tests ran'
echo "== ringct and tx_verification_utils suites $(date -u +%FT%TZ)"
$UT --gtest_filter='ringct.*:tx_verification_utils.*' > $W/build_dot9_ut_rct.log 2>&1; echo "rc=$?"; grep -E '^\[  (PASSED|FAILED) ' $W/build_dot9_ut_rct.log
echo "== crate tests $(date -u +%FT%TZ)"
cd $R/src/fcmp_pp/fcmp_pp_rust/patched/monero-oxide
CARGO_TARGET_DIR=$R/build/ctarget nice -n 5 cargo test --release -j10 -p generalized-bulletproofs --features tests > $W/build_dot9_gbp.log 2>&1; echo "gbp rc=$?"; grep -E '^test result|FAILED|panicked' $W/build_dot9_gbp.log | head
CARGO_TARGET_DIR=$R/build/ctarget nice -n 5 cargo test --release -j10 -p full-chain-membership-proofs -- --skip prove_benchmark > $W/build_dot9_fcmps.log 2>&1; echo "fcmps rc=$?"; grep -E '^test result|FAILED|panicked' $W/build_dot9_fcmps.log | head
echo "== all unit_tests $(date -u +%FT%TZ)"
cd $R && $UT > $W/build_dot9_ut_all.log 2>&1; echo "rc=$?"; grep -E '^\[  (PASSED|FAILED) |^\[  FAILED  \]' $W/build_dot9_ut_all.log | head -20
echo "free after $(df --output=avail -BG / | tail -1)"
fin ok
